package com.bitedash.service; import com.bitedash.dto.*; import com.bitedash.entity.*; import com.bitedash.exception.*; import com.bitedash.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service public class RestaurantService {private final RestaurantRepository restaurants; private final FoodItemRepository foods; public RestaurantService(RestaurantRepository r,FoodItemRepository f){restaurants=r;foods=f;} public List<RestaurantResponse> search(String s,String c){return restaurants.search(blank(s),blank(c)).stream().map(RestaurantResponse::of).toList();} public Restaurant get(Long id){return restaurants.findById(id).filter(Restaurant::isActive).orElseThrow(()->new NotFoundException("Restaurant not found"));} @Transactional(readOnly=true) public List<FoodItemResponse> items(Long id){get(id);return foods.findByRestaurantIdAndAvailableTrue(id).stream().map(FoodItemResponse::of).toList();} private String blank(String x){return x==null||x.isBlank()?null:x.trim();}}
